<?php require __DIR__.'/bootstrap.php'; if(session_status()!==PHP_SESSION_ACTIVE)session_start(); $cart=$_SESSION['cart']??[]; if(!$cart)redirect('cart.php'); $zones=array_values(array_filter(read_json('delivery-zones.json',[]),fn($z)=>!empty($z['enabled'])));$subtotal=array_sum(array_map(fn($i)=>(float)$i['line_total'],$cart));$error=''; if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$name=trim((string)($_POST['name']??''));$email=trim((string)($_POST['email']??''));$phone=trim((string)($_POST['phone']??''));$fulfil=(string)($_POST['fulfilment']??'pickup');$scheduled=trim((string)($_POST['scheduled_at']??''));$zoneId=(string)($_POST['zone_id']??'');$address=trim((string)($_POST['address']??''));$area='';$fee=0;if($fulfil==='delivery'){foreach($zones as $z)if($z['id']===$zoneId){$area=$z['name'];$fee=(float)$z['fee'];break;}} if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||!$phone||!$scheduled){$error='Please complete your name, valid email, phone number, and scheduled date/time.';}elseif($fulfil==='delivery'&&(!$area||!$address)){$error='Select an approved delivery area and enter the complete address.';}elseif(strtotime($scheduled)<time()+((int)cfg('min_lead_hours',48)*3600)){$error='Please choose a date and time at least '.(int)cfg('min_lead_hours',48).' hours from now.';}else{$ref=order_ref();$order=['reference'=>$ref,'created_at'=>date(DATE_ATOM),'customer'=>['name'=>$name,'email'=>$email,'phone'=>$phone],'items'=>$cart,'subtotal'=>$subtotal,'delivery_fee'=>$fee,'total'=>$subtotal+$fee,'fulfilment'=>$fulfil,'delivery'=>['zone_id'=>$zoneId,'area'=>$area,'address'=>$address,'landmark'=>trim((string)($_POST['landmark']??'')),'directions'=>trim((string)($_POST['directions']??''))],'scheduled_at'=>$scheduled,'payment_status'=>'pending','payment_reference'=>'','status'=>'Awaiting Payment','timeline'=>[['status'=>'Awaiting Payment','at'=>date(DATE_ATOM)]]];$orders=read_json('orders.json',[]);$orders[]=$order;write_json('orders.json',$orders);$_SESSION['pending_order_ref']=$ref;$_SESSION['cart']=[];$secret=(string)cfg('paystack_secret_key','');$payload=['email'=>$email,'amount'=>(int)round(($subtotal+$fee)*100),'currency'=>'NGN','reference'=>$ref,'callback_url'=>rtrim((string)cfg('base_url',''),'/').'/paystack-callback.php','metadata'=>['order_reference'=>$ref,'customer_name'=>$name]];$ch=curl_init('https://api.paystack.co/transaction/initialize');curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>['Authorization: Bearer '.$secret,'Content-Type: application/json'],CURLOPT_POSTFIELDS=>json_encode($payload),CURLOPT_TIMEOUT=>25]);$response=curl_exec($ch);$status=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$data=json_decode((string)$response,true);if($secret!==''&&$status>=200&&$status<300&&!empty($data['status'])&&!empty($data['data']['authorization_url'])){redirect($data['data']['authorization_url']);}else{add_notification('Paystack initialization failed','Order '.$ref.' was saved but payment initialization failed.','payment',$ref);$error='We could not start payment right now. Your order reference is '.$ref.'. Please try again later or contact the bakery. Do not pay outside the secure checkout.';}}} site_header('Checkout'); ?>
<section class="page-hero"><div class="eyebrow">Secure checkout</div><h1>Make it official.</h1><p>Choose how you'd like to receive your order and confirm your details.</p></section><section class="content"><?php if($error): ?><div class="alert error"><?= e($error) ?></div><?php endif; ?><div class="cart-layout"><form class="card-panel" method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><h2>Your details</h2><div class="field"><label>Full name *</label><input name="name" required value="<?= e($_POST['name']??'') ?>"></div><div class="form-grid"><div class="field"><label>Email address *</label><input type="email" name="email" required value="<?= e($_POST['email']??'') ?>"></div><div class="field"><label>Phone number *</label><input type="tel" name="phone" required value="<?= e($_POST['phone']??'') ?>"></div></div><h2>Fulfilment</h2><div class="field"><label>Choose delivery or pickup *</label><select name="fulfilment" id="fulfilment" onchange="document.getElementById('delivery-fields').hidden=this.value!=='delivery'"><option value="pickup">Pickup from bakery — free</option><option value="delivery">Delivery in an approved Abuja area</option></select></div><div id="delivery-fields" hidden><div class="field"><label>Delivery area *</label><select name="zone_id"><option value="">Choose area</option><?php foreach($zones as $z): ?><option value="<?= e($z['id']) ?>"><?= e($z['name']) ?> — <?= money((float)$z['fee']) ?></option><?php endforeach; ?></select></div><div class="field"><label>Full delivery address *</label><textarea name="address" placeholder="House number, street, estate, area"></textarea></div><div class="field"><label>Nearest landmark</label><input name="landmark"></div><div class="field"><label>Additional directions</label><textarea name="directions"></textarea></div></div><div class="field"><label>Requested date and time *</label><input type="datetime-local" name="scheduled_at" required min="<?= e(date('Y-m-d\TH:i',time()+((int)cfg('min_lead_hours',48)*3600))) ?>" value="<?= e($_POST['scheduled_at']??'') ?>"><small>Orders require at least <?= (int)cfg('min_lead_hours',48) ?> hours' notice. Final availability may need bakery confirmation.</small></div><div class="notice">Your order is confirmed only after Paystack payment is verified. Cancellation requests must be made by contacting Bakery Bake.</div><button class="button" type="submit" style="width:100%">Continue to secure payment ↗</button></form><aside class="card-panel"><h2>Order summary</h2><?php foreach($cart as $i): ?><div class="summary-row"><span><?= e($i['name']) ?> × <?= (int)$i['qty'] ?><br><small><?= e($i['size']) ?> · <?= e($i['flavour']) ?></small></span><strong><?= money((float)$i['line_total']) ?></strong></div><?php endforeach; ?><div class="summary-row"><span>Subtotal</span><strong><?= money($subtotal) ?></strong></div><div class="summary-row"><span>Delivery fee</span><span>Calculated from selected area</span></div><div class="summary-row total"><span>Subtotal</span><strong><?= money($subtotal) ?></strong></div><p class="muted">All prices in Nigerian naira (NGN).</p></aside></div></section><?php site_footer(); ?>
